            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belts & Tensioners", details: "Replace the main accessory drive belt, the A/C belt, and tensioner pulleys.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "110 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine & Transmission Mounts", details: "Replace the sagging rubber mounts to prevent the heavy V8 from shifting and vibrating the luxury cabin.", parts: ["Lemförder Mounts"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" },
            { interval: "100,000 km", timeLimit: "10 years", task: "Rear Integral Link (Ball Joint)", details: "Replace the rear suspension ball joints to cure aggressive squeaking and poor rear-end stability.", parts: ["Lemförder Ball Joints"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "100 EUR" }
