            { interval: "120,000 km", timeLimit: "10 years", task: "Radiator Hoses", details: "Replace the upper and lower rubber radiator hoses before they burst from age.", parts: ["Hose Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "90 EUR" },
            { interval: "4 Years", timeLimit: "4 years", task: "A/C System Service", details: "Recover, vacuum, and recharge the A/C refrigerant to maintain optimal cabin cooling in the large E38.", parts: ["R134a Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }
