            { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Guide Replacement", details: "CRITICAL: A massive, engine-front teardown to rip out the fragile factory plastic timing chain guides and replace them before they shatter and total the engine.", parts: ["Timing Guide Kit", "Special Tools"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500+ EUR" },
            { interval: "Immediately", timeLimit: "Unlimited", task: "Oil Pump Bolt Safety Wiring", details: "CRITICAL: Drop the oil pan, clean the factory oil pump bolts, apply high-strength Loctite, and safely wire them in place. If they fall out, the V8 will instantly seize.", parts: ["Oil Pan Gasket", "Safety Wire"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Reseal & PCV Plate", details: "CRITICAL: Remove the massive intake manifold, replace all four shrinking runner gaskets, and replace the rear PCV/OSV plate to cure massive vacuum leaks and rough idling.", parts: ["Intake Gaskets", "PCV Plate"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Gasket Replacement", details: "CRITICAL: Replace the massive rubber gaskets and the inner spark plug tube seals to stop oil leaking onto the hot exhaust manifolds (Fire Risk).", parts: ["2x VCG Kits"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Valley Pan Gasket Replacement", details: "While the intake manifold is removed, remove the valley pan cover plate deep in the engine 'V' and reseal it to cure hidden, persistent coolant leaks.", parts: ["Valley Pan Gasket", "Coolant Pipe O-Rings"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "200 EUR" },
            { interval: "60,000 km", timeLimit: "5 years", task: "Spark Plug Replacement", details: "Replace the spark plugs to ensure smooth operation of the V8.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Timing Chain Tensioner Replacement", details: "Proactively replace the screw-in primary timing chain tensioner on the side of the block to maintain constant pressure on the fragile plastic guides.", parts: ["Genuine Tensioner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" }
