            { interval: "150,000 km", timeLimit: "Unlimited", task: "Injector Leak-Off Pipes", details: "Replace the braided rubber return lines linking the injectors. They rot and cause air leaks in the fuel system, preventing the car from starting.", parts: ["Vacuum Hose"], importance: "High", laborDifficulty: "Easy", estimatedCost: "15 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "CRITICAL: Proactively replace the heavy main crankshaft pulley. The rubber core tears and will eventually destroy the serpentine belt system.", parts: ["Corteco Damper", "Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }
