            { interval: "40,000 km", timeLimit: "3 years", task: "Engine Coolant Flush", details: "Drain and refill the massive 14.5L cooling system with BMW Blue coolant. Vital for preserving the aluminum block and water-cooled alternator.", parts: ["14.5L G48 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "85 EUR" },
            { interval: "60,000 km", timeLimit: "5 years", task: "Power Steering / Dynamic Drive Fluid", details: "Drain and refill the specific CHF 11S fluid.", parts: ["1.0L CHF 11S"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
