            { interval: "120,000 km", timeLimit: "10 years", task: "Radiator Hoses", details: "Replace the massive upper and lower rubber radiator hoses before they burst from age.", parts: ["Hose Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 EUR" },
            { interval: "4 Years", timeLimit: "4 years", task: "A/C System Service", details: "Recover, vacuum, and recharge the A/C refrigerant.", parts: ["R134a Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }
