            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Replace the accessory drive belt and tensioner pulley to prevent belt snapping.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine & Transmission Mounts", details: "Replace the complex vacuum-actuated fluid engine mounts if they are leaking or causing excessive cabin vibration.", parts: ["Lemförder Mounts"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "220 EUR" }
