        { interval: "40,000 km", timeLimit: "3 years", task: "Engine Coolant Flush", details: "Drain and refill the primary engine cooling system with BMW HT-12 coolant.", parts: ["10.0L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
        { interval: "40,000 km", timeLimit: "3 years", task: "Charge-Air Coolant Flush", details: "Drain and refill the separate low-temperature intercooler cooling circuit. Critical for B58 intake temps.", parts: ["3.2L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" },
        { interval: "Every Service", timeLimit: "1 year", task: "Windshield Washer Fluid Check", details: "Top up washer fluid and thoroughly inspect pump operation.", parts: ["Washer Fluid"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "10 EUR" }
