        { interval: "40,000 km", timeLimit: "3 years", task: "Engine Coolant Flush", details: "Drain and refill the primary engine cooling system with BMW HT-12 coolant.", parts: ["10.0L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
        { interval: "40,000 km", timeLimit: "3 years", task: "High-Voltage Electronics Coolant Flush", details: "CRITICAL: Drain and refill the separate cooling circuit dedicated to the EME inverter and electric motor. Failure leads to catastrophic hybrid meltdown.", parts: ["3.5L HT-12 Coolant"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "100 EUR" }
