        { interval: "100,000 km", timeLimit: "8 years", task: "Intercooler Leak Inspection", details: "Visually inspect the charge pipes for signs of coolant mixing. A leaking internal intercooler will slowly destroy the engine.", parts: ["Inspection Labor"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }
