        { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "CRITICAL: Remove the massive intake manifolds and blast the 24 intake ports with crushed walnut shells to clear the massive carbon sludge buildup caused by the direct injection system.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "600 EUR" },
        { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover & Upper Timing Cover Gaskets", details: "CRITICAL: Remove the complex Valvetronic motors, replace the incredibly long rubber gaskets, and reseal the upper timing covers to stop oil leaking onto the hot twin turbos.", parts: ["VCG Sets", "Timing Cover Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "600 EUR" },
        { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plug & Coil Replacement", details: "Replace the 12 spark plugs to ensure smooth operation of the massive V12.", parts: ["12x NGK Plugs", "12x Eldor Coils"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" },
        { interval: "100,000 km", timeLimit: "Unlimited", task: "VANOS Solenoid Cleaning/Replacement", details: "Remove and clean the fine mesh screens on the four VANOS solenoids to cure hesitation and rough idle.", parts: ["O-Rings", "Brake Cleaner"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" },
        { interval: "150,000 km", timeLimit: "Unlimited", task: "High-Pressure Fuel Pump (HPFP)", details: "CRITICAL: If long cranks or half-engine lights occur under heavy acceleration, the mechanical HPFPs must be replaced.", parts: ["2x Genuine HPFPs"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "2500+ EUR" },
        { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Guide Replacement", details: "CRITICAL: If loud rattling is heard on cold start, the incredibly brittle plastic timing guides must be replaced before they shatter and the chain jumps a tooth, destroying the engine.", parts: ["Timing Guide Kit", "Special Tools"], importance: "High", laborDifficulty: "Expert", estimatedCost: "3000+ EUR" }
